__declspec(noinline) G3D::Matrix3 Block::getMomentHollow(float mass) const
{
	G3D::Vector3 grid = gridSize;
	G3D::Vector3 I;

	float area = ((grid.x * grid.z + grid.y * grid.z) + grid.x * grid.y) * 2;

	for (int i = 0; i < 3; i++)
	{
		float X = grid[(i    ) % 3];
		float Y = grid[(i + 1) % 3];
		float Z = grid[(i + 2) % 3];

		float scaling = mass / (2 * area);

		float temp = (Z*Z*Y)*X + (Y*Y*Y*Z)/3 + (Z*Z*Z*Y)/3 + (Y*Y*Z)*X + (X*Y*Y*Y)/3 + (X*Z*Z*Z)/3;

		I[i] = temp * scaling;
	}

	return Math::fromDiagonal(I);
}

__declspec(noinline) G3D::Matrix3 Block::getMomentHollow(float mass) const
{
	G3D::Vector3 size = gridSize;

	float area = 2 * (size.x * size.y + size.y * size.z + size.z * size.x);
	G3D::Vector3 I;
	for (int i = 0; i < 3; i++) {
		int j = (i + 1) % 3;
		int k = (i + 2) % 3;
		float x = size[i];		// main axis;
		float y = size[j];
		float z = size[k];

		float Ix = (mass / (2.0f * area)) * (		(y*y*y*z/3.0f)
												+	(y*z*z*z/3.0f)
												+	(x*y*z*z)
												+	(x*y*y*y/3.0f)
												+	(x*y*y*z)
												+	(x*z*z*z/3.0f)	);
		I[i] = Ix;
	}
	return Math::fromDiagonal(I);
}

