Block::getEdgePoint(const G3D::Vector3int16& clip, NormalId& normalID) const
	{
		if (clip.x == 0)
		{
			normalID = NORM_X;
			return &this->vertices[2 * (clip.y <= 0) + 4 + (clip.z <= 0)];
		}
		else if (clip.y == 0)
		{
			normalID = NORM_Y;
			return &this->vertices[4 * (clip.x <= 0) + 2 + (clip.z <= 0)];
		}
		else
		{
			RBXASSERT(clip.z == 0);
			normalID = NORM_Z;
			return &this->vertices[4 * (clip.x <= 0) + 1 + 2 * (clip.y <= 0)];
		}
	}

