		return &this->vertices[2 * (clip.y <= 0) + 4 + (clip.z <= 0)];
	}
	else if (clip.y == 0)
	{
		normalID = NORM_Y;
		return &this->vertices[4 * (clip.x <= 0) + 2 + (clip.z <= 0)];
	}
	else
	{
		normalID = NORM_Z;
